  "authored by lingofi academic board at iiui. a reflective inquiry into internal serenity, modern alienation, and rediscovering human contentment through introspection.": {
      "es": "Escrito por LingoFi Academic Board en IIUI. Una indagación reflexiva sobre la serenidad interior, la alienación moderna y el redescubrimiento del contento humano a través de la introspección.",
      "fr": "Écrit par LingoFi Academic Board à l'IIUI. Une réflexion profonde sur la sérénité intérieure, l'aliénation moderne et la redécouverte du contentement à travers l'introspection.",
      "de": "Verfasst von LingoFi Academic Board an der IIUI. Eine reflektierte Auseinandersetzung mit innerer Gelassenheit, moderner Entfremdung und der Wiederentdeckung menschlicher Zufriedenheit.",
      "zh": "由 LingoFi Academic Board 在 IIUI 创作。深入探讨现代人内心的宁静与焦虑、科技异化以及通过内省重拾生命本真幸福的哲学著作。",
      "ar": "مؤلف بواسطة مجلس LingoFi الأكاديمي في IIUI. بحث تأملي في الصفاء الداخلي، والاغتراب الحديث، وإعادة اكتشاف الرضا البشري من خلال الاستبطان والتأمل.",
      "hi": "आईआईयूआई में LingoFi अकादमिक बोर्ड द्वारा लिखित। आंतरिक शांति, आधुनिक अलगाव और आत्मनिरीक्षण के माध्यम से मानवीय संतोष की खोज पर एक विचारशील जांच।",
      "pt": "De autoria de LingoFi Academic Board na IIUI. Uma investigação reflexiva sobre a serenidade interior, a alienação moderna e a redescoberta do contentamento humano.",
      "ru": "Автор — Академический совет LingoFi (IIUI). Размышление о внутреннем спокойствии, современном отчуждении и обретении душевного равновесия через самопознание.",
      "ja": "IIUIにてLingoFi学術評議会が執筆。内なる静寂、現代社会における孤独・疎外感、そして内省を通じた真の人間的幸福の再発見を問いかける思索的散文作品。",
      "ur": "IIUI میں LingoFi اکیڈمک بورڈ کی تصنیف۔ اندرونی سکون، جدید بیگانگی، اور خود شناسی کے ذریعے انسانی اطمینان کی بازیافت پر ایک فکری مطالعہ۔",
      "bn": "আইআইইউআই-তে LingoFi একাডেমিক বোর্ড রচিত। অভ্যন্তরীণ প্রশান্তি, আধুনিক বিচ্ছিন্নতা এবং আত্মদর্শনের মাধ্যমে মানুষের তৃপ্তি পুনঃআবিষ্কারের ওপর একটি চিন্তাশীল অনুসন্ধান।"
    },
