  "manual score editing is strictly disabled. scores are securely recorded from your highest-scoring test attempts.": {
      "es": "La edición manual de puntuaciones está estrictamente desactivada. Las puntuaciones se registran de forma segura a partir de sus mejores intentos en las pruebas.",
      "fr": "La modification manuelle des scores est strictement désactivée. Les scores sont enregistrés de manière sécurisée à partir de vos meilleures tentatives.",
      "de": "Die manuelle Bearbeitung von Prüfungsergebnissen ist strengstens untersagt. Die Ergebnisse werden manipulationssicher aus Ihren besten Testversuchen übernommen.",
      "zh": "系统严格禁止手动修改测试成绩。所有成绩均通过考生历史模考中的最高分自动加密归档。",
      "ar": "تعديل الدرجات يدوياً معطل تماماً. تُسجل الدرجات بأمان فائق من أعلى محاولاتك في الاختبارات.",
      "hi": "स्कोर का मैन्युअल संपादन पूरी तरह से अक्षम है। आपके उच्चतम स्कोर वाले टेस्ट प्रयासों से स्कोर सुरक्षित रूप से दर्ज किए जाते हैं।",
      "pt": "A edição manual de notas está estritamente desativada. As pontuações são gravadas com segurança a partir de suas melhores tentativas de teste.",
      "ru": "Ручное редактирование баллов строго запрещено. Баллы надежно фиксируются на основе ваших лучших попыток сдачи тестов.",
      "ja": "スコアの手動編集は厳格に禁止されています。成績は受験した最高得点のテスト結果から安全に自動記録されます。",
      "ur": "اسکورز میں دستی ترمیم کی قطعی اجازت نہیں ہے۔ اسکورز آپ کے سب سے زیادہ نمبروں والے ٹیسٹ سے خودکار اور محفوظ طریقے سے درج کیے جاتے ہیں۔",
      "bn": "ম্যানুয়াল স্কোর সম্পাদনা কঠোরভাবে নিষ্ক্রিয়। স্কোরগুলি আপনার সর্বোচ্চ স্কোরিং পরীক্ষার প্রচেষ্টা থেকে নিরাপদে রেকর্ড করা হয়।"
    },
