  "replicates the actual idp and british council exam interface with dual-pane reading passages, audio controls, live word counters, and strict timed countdown clocks.": {
      "es": "Reproduce la interfaz de examen real de IDP y British Council con textos de lectura en panel doble, controles de audio, contadores de palabras en vivo y estrictos relojes de cuenta regresiva.",
      "fr": "Reproduit l'interface d'examen réelle de l'IDP et du British Council avec affichage bivolet des textes, commandes audio, compteurs de mots en direct et compteurs à rebours stricts.",
      "de": "Repliziert die tatsächliche Prüfungsoberfläche von IDP und British Council mit zweispaltigen Lesetexten, Audiosteuerungen, Live-Wortzählern und strengen Countdown-Uhren.",
      "zh": "1:1 深度还原 IDP 与英国文化协会真实机考界面，包含双栏分屏阅卷、听力音频控制条、实时写作字数统计与严格的考场倒计时时钟。",
      "ar": "يحاكي واجهة الاختبار الفعلية لـ IDP والمجلس الثقافي البريطاني مع نصوص قراءة مزدوجة وعناصر تحكم بالصوت وعداد كلمات وساعات توقيت دقيقة.",
      "hi": "आईडीपी और ब्रिटिश काउंसिल के वास्तविक परीक्षा इंटरफ़ेस को दोहरे फलक वाले पठन अंशों, ऑडियो नियंत्रणों, लाइव शब्द काउंटरों और समयबद्ध घड़ियों के साथ दोहराता है।",
      "pt": "Replica a interface real de exame do IDP e British Council com passagens de leitura em painel duplo, controles de áudio, contadores de palavras e relógios de contagem regressiva.",
      "ru": "Точно воспроизводит реальный интерфейс экзамена IDP и British Council с двухпанельным чтением, элементами управления звуком, счетчиками слов и точными таймерами.",
      "ja": "2ペイン構成のリーディング読解画面、音声操作パネル、リアルタイム単語数カウンター、厳密なカウントダウン時計など、IDPやブリティッシュ・カウンシルの本番機考画面を忠実に再現。",
      "ur": "آئی ڈی پی اور برٹش کونسل کے اصل امتحانی انٹرفیس کی نقل کرتا ہے جس میں دو پین والے ریڈنگ پیراگراف، آڈیو کنٹرول، لائیو ورڈ کاؤنٹر اور سخت ٹائمرز شامل ہیں۔",
      "bn": "ডুয়াল-পেন পঠন অনুচ্ছেদ, অডিও নিয়ন্ত্রণ, লাইভ শব্দ কাউন্টার এবং কঠোর কাউন্টডাউন ঘড়ি সহ আসল আইডিপি এবং ব্রিটিশ কাউন্সিল পরীক্ষার ইন্টারফেসের প্রতিলিপি তৈরি করে।"
    },
