  "lingofi is maintained under lingofi academic board's autonomous academic stewardship, adhering strictly to cambridge esol and idp alignment criteria.": {
      "es": "LingoFi se mantiene bajo la tutela académica autónoma de LingoFi Academic Board, adhiriéndose estrictamente a los criterios de alineación de Cambridge ESOL y el IDP.",
      "fr": "LingoFi est géré sous la direction académique autonome de LingoFi Academic Board, en stricte conformité avec les critères de Cambridge ESOL et de l'IDP.",
      "de": "LingoFi wird unter der eigenverantwortlichen akademischen Leitung von LingoFi Academic Board geführt und hält sich strikt an die Kriterien von Cambridge ESOL und IDP.",
      "zh": "LingoFi 始终在 LingoFi Academic Board 的自主学术引领下独立运作，严格遵守剑桥ESOL与IDP雅思官方大纲对齐标准。",
      "ar": "تُدار منصة LingoFi تحت الإشراف الأكاديمي المستقل لمجلس LingoFi، مع الالتزام التام بمعايير كامبريدج وIDP.",
      "hi": "LingoFi अकादमिक बोर्ड की स्वायत्त देखरेख में संचालित होता है, जो कैम्ब्रिज ईएसओएल और आईडीपी संरेखण मानदंडों का सख्ती से पालन करता है।",
      "pt": "O LingoFi é mantido sob a tutela acadêmica autônoma de LingoFi Academic Board, aderindo estritamente aos critérios de alinhamento de Cambridge ESOL e IDP.",
      "ru": "LingoFi поддерживается под независимым академическим руководством Академического совета LingoFi в строгом соответствии со стандартами Cambridge ESOL и IDP.",
      "ja": "LingoFiは、ケンブリッジESOLおよびIDPの基準に厳格に準拠し、LingoFi学術評議会の指導のもとで維持・運営されています。",
      "ur": "LingoFi خودمختار تعلیمی رہنمائی میں چلایا جاتا ہے، جو کیمبرج اور IDP کے معیارات کی سختی سے پیروی کرتا ہے۔",
      "bn": "LingoFi একাডেমিক বোর্ডের স্বায়ত্তশাসিত তত্ত্বাবধানে পরিচালিত হয়, যা কেমব্রিজ ইএসওএল এবং আইডিপি সমন্বয় মানদণ্ড কঠোরভাবে মেনে চলে।"
    },
