  "• avoid one-word answers (\"yes\" or \"no\"). always extend your answers with 2–3 sentences giving a reason or example.": {
      "es": "• Evite respuestas de una sola palabra (\"Sí\" o \"No\"). Amplíe siempre sus respuestas con 2 o 3 oraciones explicando un motivo o aportando un ejemplo.",
      "fr": "• Évitez les réponses d'un seul mot (« Oui » ou « Non »). Développez toujours vos réponses avec 2 à 3 phrases en donnant une raison ou un exemple.",
      "de": "• Vermeiden Sie Ein-Wort-Antworten („Ja“ oder „Nein“). Erweitern Sie Ihre Antworten stets um 2–3 Sätze mit Begründung oder Beispiel.",
      "zh": "• 切忌单一字词作答（严禁仅回答“Yes”或“No”）。务必运用2–3句话展开阐述，给出充分的论据支持或具体生活实例。",
      "ar": "• تجنب الإجابات بكلمة واحدة (\"نعم\" أو \"لا\"). وسّع إجابتك دائماً بجملتين إلى ثلاث جمل مع ذكر سبب أو تقديم مثال توضيحي.",
      "hi": "• एक-शब्द के उत्तर (\"हाँ\" या \"नहीं\") से बचें। हमेशा कारण या उदाहरण देते हुए 2-3 वाक्यों के साथ अपने उत्तरों का विस्तार करें।",
      "pt": "• Evite respostas de uma palavra só (\"Sim\" ou \"Não\"). Sempre amplie suas respostas com 2 a 3 frases dando um motivo ou exemplo.",
      "ru": "• Избегайте односложных ответов («Да» или «Нет»). Всегда дополняйте ответ 2–3 предложениями с обоснованием или примером.",
      "ja": "• 「Yes」や「No」の一言だけの回答は避けてください。理由や具体例を付け加えて2〜3文で必ず話を広げましょう。",
      "ur": "• ایک لفظ والے جوابات (\"ہاں\" یا \"نہیں\") سے گریز کریں۔ ہمیشہ وجہ یا مثال دیتے ہوئے 2 سے 3 جملوں میں جواب کو وسعت دیں۔",
      "bn": "• এক শব্দের উত্তর (\"হ্যাঁ\" বা \"না\") এড়িয়ে চলুন। সর্বদা একটি কারণ বা উদাহরণ দিয়ে ২-৩টি বাক্যে আপনার উত্তর প্রসারিত করুন।"
    },
  "• speak naturally at a steady pace without memorizing responses.": {
      "es": "• Hable con naturalidad a un ritmo constante sin memorizar respuestas preparadas.",
      "fr": "• Parlez naturellement à un rythme régulier sans réciter de réponses mémorisées.",
      "de": "• Sprechen Sie natürlich und in gleichmäßigem Tempo, ohne auswendig gelernte Antworten aufzusagen.",
      "zh": "• 保持匀速、自然从容的口语语调作答，切勿死记硬背或机械背诵模板答案。",
      "ar": "• تحدث بتلقائية وطبيعية وبوتيرة ثابتة دون حفظ الإجابات مسبقاً وتسميعها.",
      "hi": "• उत्तरों को रटे बिना स्थिर गति से स्वाभाविक रूप से बोलें।",
      "pt": "• Fale naturalmente em um ritmo constante sem memorizar respostas prontas.",
      "ru": "• Говорите естественно в ровном темпе, избегая заученных шаблонных ответов.",
      "ja": "• 丸暗記したフレーズを暗唱するのではなく、自然かつ一定のペースで落ち着いて話しましょう。",
      "ur": "• جوابات کو رٹے بغیر قدرتی انداز میں ایک مستقل رفتار سے بولیں۔",
      "bn": "• মুখস্থ উত্তর না দিয়ে স্বাভাবিকভাবে স্থির গতিতে কথা বলুন।"
    },
  "• structure answers with the p.e.e.l method: point → explanation → example → link back.": {
      "es": "• Estructure sus respuestas con el método P.E.E.L: Punto principal → Explicación → Ejemplo → Conexión final.",
      "fr": "• Structurez vos réponses avec la méthode P.E.E.L : Point clé → Explication → Exemple → Lien de conclusion.",
      "de": "• Strukturieren Sie Ihre Antworten nach der P.E.E.L-Methode: Point → Explanation → Example → Link back.",
      "zh": "• 熟练运用P.E.E.L黄金论证法则构思回答：核心论点（Point）→ 深度阐述（Explanation）→ 具体案例（Example）→ 回扣总结（Link back）。",
      "ar": "• قسّم ونظّم إجاباتك وفق منهجية P.E.E.L: النقطة الرئيسية ← الشرح والتفسير ← مثال واقعي ← الربط بالموضوع.",
      "hi": "• P.E.E.L पद्धति से उत्तरों को व्यवस्थित करें: बिंदु → व्याख्या → उदाहरण → पुनः जोड़ना।",
      "pt": "• Estruture suas respostas com o método P.E.E.L: Ponto principal → Explicação → Exemplo → Conexão final.",
      "ru": "• Структурируйте ответы по методу P.E.E.L: Тезис → Объяснение → Пример → Связка с темой.",
      "ja": "• P.E.E.Lメソッドで回答を論理構成：Point（要点）→ Explanation（説明）→ Example（具体例）→ Link back（結論への接続）。",
      "ur": "• اپنے جوابات کو P.E.E.L طریقہ کار کے مطابق ترتیب دیں: نکتہ ← وضاحت ← مثال ← بنیادی بات سے دوبارہ ربط۔",
      "bn": "• P.E.E.L পদ্ধতিতে উত্তর গঠন করুন: পয়েন্ট → ব্যাখ্যা → উদাহরণ → মূল বিষয়ে ফিরে আসা।"
    },
  "• use speculative modal verbs (\"could potentially lead to...\", \"one plausible outcome might be...\").": {
      "es": "• Utilice verbos modales especulativos (\"podría conducir potencialmente a...\", \"un resultado verosímil podría ser...\").",
      "fr": "• Utilisez des verbes modaux de spéculation (« pourrait potentiellement mener à... », « une issue plausible pourrait être... »).",
      "de": "• Nutzen Sie spekulative Modalverben („could potentially lead to...“, „one plausible outcome might be...“).",
      "zh": "• 善用推测性情态动词与高级学术句型（如 \"could potentially lead to...\", \"one plausible outcome might be...\"）。",
      "ar": "• استخدم الأفعال الناقصة الاستنتاجية (\"قد يؤدي ذلك إلى...\", \"إحدى النتائج المحتملة قد تكون...\").",
      "hi": "• काल्पनिक मोडल क्रियाओं का प्रयोग करें (\"संभावित रूप से कारण बन सकता है...\", \"एक संभावित परिणाम हो सकता है...\")।",
      "pt": "• Utilize verbos modais especulativos (\"poderia potencialmente levar a...\", \"um resultado plausível poderia ser...\").",
      "ru": "• Используйте предположительные модальные глаголы («could potentially lead to...», «one plausible outcome might be...»).",
      "ja": "• 推量・仮定の助動詞表現を活用する（「could potentially lead to...」「one plausible outcome might be...」など）。",
      "ur": "• قیاسی افعال کا استعمال کریں (\"ممکنہ طور پر اس کا نتیجہ ہو سکتا ہے...\", \"ایک معقول نتیجہ یہ ہو سکتا ہے...\")۔",
      "bn": "• অনুমানমূলক মোডাল ক্রিয়া ব্যবহার করুন (\"সম্ভাব্যভাবে পরিচালিত করতে পারে...\", \"একটি সম্ভাব্য ফলাফল হতে পারে...\")।"
    },
